'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var format = require( '@stdlib/string/format' );
var copy = require( '@stdlib/utils/copy' );
var isSafeToken = require( '@stdlib/utils/json-pointer/base/assert/is-safe-token' );
var resolveToken = require( '@stdlib/utils/json-pointer/base/resolve-token' );


// MAIN //

/**
* Immutably inserts a value into an array at a path in a document using structural sharing.
*
* @param {(Object|Array)} document - source document
* @param {Array<string>} tokens - array of reference tokens
* @param {*} value - value to insert
* @throws {Error} tokens must not be empty
* @throws {Error} tokens must not contain unsafe tokens
* @throws {TypeError} intermediate path segments must reference objects or arrays
* @throws {TypeError} target container must be an array
* @throws {RangeError} index must be within bounds (0 to array.length)
* @returns {(Object|Array)} new document with the value inserted
*
* @example
* var doc = {
*     'a': [ 1, 2, 3 ]
* };
* var out = insert( doc, [ 'a', '1' ], 99 );
* // returns { 'a': [ 1, 99, 2, 3 ] }
*
* var bool = ( doc.a === out.a );
* // returns false
*
* bool = ( doc === out );
* // returns false
*/
function insert( document, tokens, value ) {
	var current;
	var child;
	var root;
	var key;
	var i;

	if ( tokens.length === 0 ) {
		throw new Error( 'invalid argument. Cannot insert at the root of a document.' );
	}

	root = copy( document, 1 );
	current = root;

	// Walk all tokens except the last, cloning each level:
	for ( i = 0; i < tokens.length - 1; i++ ) {
		if ( !isSafeToken( tokens[ i ] ) ) {
			throw new Error( format( 'invalid argument. Token contains an unsafe value. Value: `%s`.', tokens[ i ] ) );
		}
		key = resolveToken( current, tokens[ i ] );

		if ( !isPlainObject( current[ key ] ) && !isArray( current[ key ] ) ) {
			throw new TypeError( format( 'invalid argument. Path references a non-traversable value at token `%s`.', tokens[ i ] ) );
		}
		child = copy( current[ key ], 1 );
		current[ key ] = child;
		current = child;
	}

	// The final container must be an array for insert operations:
	if ( !isArray( current ) ) {
		throw new TypeError( format( 'invalid argument. Insert target must be an array. Token: `%s`.', tokens[ tokens.length - 1 ] ) );
	}
	if ( !isSafeToken( tokens[ tokens.length - 1 ] ) ) {
		throw new Error( format( 'invalid argument. Token contains an unsafe value. Value: `%s`.', tokens[ tokens.length - 1 ] ) );
	}

	key = resolveToken( current, tokens[ tokens.length - 1 ] );
	if ( key < 0 || key > current.length ) {
		throw new RangeError( format( 'invalid argument. Array index out of bounds for insert. Index: `%d`. Length: `%d`.', key, current.length ) );
	}
	current.splice( key, 0, value );

	return root;
}


// EXPORTS //

module.exports = insert;
